import TicketMainColumn from './tickets/TicketMainColumn';
import TicketLightbox from './tickets/TicketLightbox';
import TicketHistory from './tickets/TicketHistory';
import { useLocation, useNavigate } from 'react-router-dom';
import React from 'react';
import DictationButton from '../shared/DictationButton';
import { safe } from '../../utils/safeRender';
import { safeParseDate } from '../../utils/dateHelpers';
import ConfirmModal from './ConfirmModal';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '../../firebase';
import { compressImage } from '../../utils/imageCompressor';
import Toast from './Toast';
import MachineDTR from './MachineDTR';
import { USER_ROLES, TICKET_STATUS } from '../../utils/constants';

export default function TicketDetails({
  machines,
  regions,
  currentTicket,
  setSelectedTicketId,
  user,
  services,
  handleUpdate,
  handleDeleteTicket,
  handleArchiveTicket,
  comment,
  setComment,
  selectedService,
  setSelectedService,
  etr,
  setEtr,
  loading,
  allowTicketDeletion,
  showToast,
  showConfirm,
  STATUSES,
  isArchive
}) {
  const location = useLocation();
  const navigate = useNavigate();
  const [lightboxImg, setLightboxImg] = React.useState(null);
  const [uploadedPhotos, setUploadedPhotos] = React.useState([]);
  const [uploadProgress, setUploadProgress] = React.useState('');
  const [isUploading, setIsUploading] = React.useState(false);
  const [uploadError, setUploadError] = React.useState(null);

  
  // Czas pracy
  const machine = machines?.find(m => m.id === currentTicket.machineId);
  const machineName = machine?.name || currentTicket.machineName || 'Maszyna usunięta';
  const machineRegion = machine ? machine.regionId : null;

  const duration = currentTicket.closedAt && currentTicket.startedAt ? 
    ((new Date(currentTicket.closedAt) - new Date(currentTicket.startedAt))/1000/3600).toFixed(1) : 
    (parseInt(currentTicket.status, 10) === 5 || currentTicket.status === 'closed' ? '0.0' : '-');

    return (
      <div className="bg-[#f8f9fa] w-full flex flex-col h-full overflow-y-auto animate-fade-in relative text-[#111827]">
        

        {/* Górny pasek nawigacyjny z przyciskiem powrotu */}
        <div className="p-2 md:p-4 border-b border-gray-200 bg-white sticky top-0 z-20 flex flex-wrap justify-between items-center gap-2 shadow-sm">
          <div className="flex flex-wrap gap-2 md:gap-4">
            
            {location.state?.backToMachineId && (
              <button onClick={() => { const returnId = location.state?.backToMachineId; if (returnId) { navigate(`/manager/master_data/machines?openMachine=${returnId}`); } }} className="flex items-center gap-1.5 bg-slate-700 hover:bg-slate-800 text-white px-3 py-1.5 md:px-5 md:py-2.5 text-xs md:text-base rounded-md md:rounded-lg font-bold shadow-md transition-all">
                <i className="ph ph-arrow-u-up-left text-lg"></i>
                Wróć do Urządzenia
              </button>
            )}
            <button onClick={() => window.history.back()} className="flex items-center gap-1.5 bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 md:px-5 md:py-2.5 text-xs md:text-base rounded-md md:rounded-lg font-bold shadow-md transition-all">
              <i className="ph ph-arrow-left text-lg"></i> Powrót do rejestru
            </button>
            <button onClick={() => import('../../utils/reports/pdfTicketCard').then(m => m.generateTicketPDF(currentTicket))} className="flex items-center gap-1.5 bg-slate-100 hover:bg-slate-200 border border-slate-300 text-slate-700 px-3 py-1.5 md:px-5 md:py-2.5 text-xs md:text-base rounded-md md:rounded-lg font-bold shadow-sm transition-all">
              <i className="ph ph-file-pdf text-xl text-red-600"></i> Karta PDF
            </button>
            
          </div>
        </div>

        <div className="p-4 w-full px-2 sm:px-4 md:px-6">
          <div className="flex flex-col lg:flex-row gap-4 sm:gap-6">
            
            {/* LEWA KOLUMNA (Główna sekcja + Stepper) */}
            <TicketMainColumn
              machines={machines}
              currentTicket={currentTicket}
              machineName={machineName}
              machineRegion={machineRegion}
              regions={regions}
              duration={duration}
              STATUSES={STATUSES}
              user={user}
              loading={loading}
              isArchive={isArchive}
              services={services}
              selectedService={selectedService}
              setSelectedService={setSelectedService}
              etr={etr}
              setEtr={setEtr}
              comment={comment}
              setComment={setComment}
              handleUpdate={handleUpdate}
              handleDeleteTicket={handleDeleteTicket}
              handleArchiveTicket={handleArchiveTicket}
              allowTicketDeletion={allowTicketDeletion}
              setLightboxImg={setLightboxImg}
            />

            {/* PRAWA KOLUMNA (Historia Zdarzen) */}
            <div className="w-full lg:w-1/4">
              <TicketHistory history={currentTicket.history} setLightboxImg={setLightboxImg} />
            </div>
          </div>
        </div>

      {machines?.some(m => m.id === currentTicket.machineId) && (
        <div className="mt-8">
          <MachineDTR machine={machines?.find(m => m.id === currentTicket.machineId)} user={user} canManage={user?.role === 'manager' || (user?.role === USER_ROLES.ADMIN || user?.role === USER_ROLES.SUPERADMIN)} canDeleteNotes={(user?.role === 'admin' || user?.role === 'superadmin') || (user?.permissions || []).includes('delete_tech_notes')} />
        </div>
      )}

      <TicketLightbox lightboxImg={lightboxImg} setLightboxImg={setLightboxImg} />
      </div>
    );
}